# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TÜRKLERİN İSLAMİYET\'İ KABUL SÜRECİ (TARİHSEL AKIŞ)</text>\n  <rect x="20" y="48" width="150" height="125" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="95" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">İlk Temaslar (7. Yy)</text>\n  <text x="95" y="92" text-anchor="middle" font-size="11" fill="#78350f">Hz. Ömer ve Hz. Osman</text>\n  <text x="95" y="110" text-anchor="middle" font-size="11" fill="#78350f">döneminde Horasan ve</text>\n  <text x="95" y="128" text-anchor="middle" font-size="11" fill="#78350f">Maveraünnehir sınır</text>\n  <text x="95" y="146" text-anchor="middle" font-size="11" fill="#78350f">komşuluğu başladı.</text>\n\n  <line x1="170" y1="110" x2="188" y2="110" stroke="#475569" stroke-width="2"/>\n  <polygon points="188,105 196,110 188,115" fill="#475569"/>\n\n  <rect x="196" y="48" width="150" height="125" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="271" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">751 Talas Savaşı</text>\n  <text x="271" y="92" text-anchor="middle" font-size="11" fill="#1e3a8a">Karluk Türkleri, Çin\'e</text>\n  <text x="271" y="110" text-anchor="middle" font-size="11" fill="#1e3a8a">karşı Abbasileri</text>\n  <text x="271" y="128" text-anchor="middle" font-size="11" fill="#1e3a8a">destekledi; dostluk ve</text>\n  <text x="271" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">kitlesel İslamlaşma başladı.</text>\n\n  <line x1="346" y1="110" x2="364" y2="110" stroke="#475569" stroke-width="2"/>\n  <polygon points="364,105 372,110 364,115" fill="#475569"/>\n\n  <rect x="372" y="48" width="150" height="125" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="447" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Karahanlılar (10. Yy)</text>\n  <text x="447" y="92" text-anchor="middle" font-size="11" fill="#14532d">Satuk Buğra Han</text>\n  <text x="447" y="110" text-anchor="middle" font-size="11" fill="#14532d">(Abdülkerim) döneminde</text>\n  <text x="447" y="128" text-anchor="middle" font-size="11" fill="#14532d">Orta Asya\'da ilk büyük</text>\n  <text x="447" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Müslüman Türk devleti.</text>\n\n  <line x1="522" y1="110" x2="540" y2="110" stroke="#475569" stroke-width="2"/>\n  <polygon points="540,105 548,110 540,115" fill="#475569"/>\n\n  <rect x="548" y="48" width="132" height="125" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="614" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Anadolu &amp; Balkanlar</text>\n  <text x="614" y="92" text-anchor="middle" font-size="11" fill="#581c87">Gazneli, Selçuklu ve</text>\n  <text x="614" y="110" text-anchor="middle" font-size="11" fill="#581c87">Osmanlılar ile İslam</text>\n  <text x="614" y="128" text-anchor="middle" font-size="11" fill="#581c87">Anadolu ve Avrupa\'ya</text>\n  <text x="614" y="146" text-anchor="middle" font-size="11" fill="#581c87">taşındı.</text>\n\n  <rect x="20" y="190" width="660" height="54" rx="8" fill="#f1f5f9" stroke="#64748b" stroke-width="1.5"/>\n  <text x="350" y="212" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">ÖNEMLİ TARİHÎ BİLGİ</text>\n  <text x="350" y="232" text-anchor="middle" font-size="11" fill="#334155">Abbasiler döneminde Türkler için Bağdat yakınlarında Samerra şehri ve sınır boylarında Avasım şehirleri kurulmuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TÜRK İNANÇ VE TÖRESİ İLE İSLAM ESASLARININ UYUMU</text>\n  <rect x="30" y="45" width="285" height="195" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="172" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">İSLAM ÖNCESİ TÜRK KÜLTÜRÜ</text>\n  <text x="45" y="96" font-size="12" fill="#0c4a6e">• Tek ve soyut <tspan font-weight="bold">Gök Tanrı</tspan> inancı</text>\n  <text x="45" y="122" font-size="12" fill="#0c4a6e">• <tspan font-weight="bold">Uçmağ</tspan> (Cennet) ve <tspan font-weight="bold">Tamu</tspan> (Cehennem)</text>\n  <text x="45" y="148" font-size="12" fill="#0c4a6e">• <tspan font-weight="bold">Cihan Hâkimiyeti</tspan> Mefkûresi (Alp tipi)</text>\n  <text x="45" y="174" font-size="12" fill="#0c4a6e">• Kurban sunma ve ruhun ölümsüzlüğü</text>\n  <text x="45" y="200" font-size="12" fill="#0c4a6e">• Adalet, iffet, temizlik ve cömertlik töresi</text>\n\n  <text x="350" y="96" text-anchor="middle" font-size="16" font-weight="bold" fill="#16a34a">⟷</text>\n  <text x="350" y="122" text-anchor="middle" font-size="16" font-weight="bold" fill="#16a34a">⟷</text>\n  <text x="350" y="148" text-anchor="middle" font-size="16" font-weight="bold" fill="#16a34a">⟷</text>\n  <text x="350" y="174" text-anchor="middle" font-size="16" font-weight="bold" fill="#16a34a">⟷</text>\n  <text x="350" y="200" text-anchor="middle" font-size="16" font-weight="bold" fill="#16a34a">⟷</text>\n\n  <rect x="385" y="45" width="285" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="527" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İSLAM İNANÇ VE AHLAK ESASLARI</text>\n  <text x="400" y="96" font-size="12" fill="#14532d">• <tspan font-weight="bold">Tevhid</tspan> (Allah\'ın birliği ve eşsizliği) inancı</text>\n  <text x="400" y="122" font-size="12" fill="#14532d">• <tspan font-weight="bold">Ahiret</tspan> hayatı, cennet ve cehennem inancı</text>\n  <text x="400" y="148" font-size="12" fill="#14532d">• <tspan font-weight="bold">Cihat / Gaza</tspan> (Alperen / Gazi ruhu)</text>\n  <text x="400" y="174" font-size="12" fill="#14532d">• Allah rızası için kurban ve sadaka ibadeti</text>\n  <text x="400" y="200" font-size="12" fill="#14532d">• Güzel ahlak, taharet ve kul hakkı bilinci</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HORASAN, ANADOLU VE BALKANLAR\'DA İSLAMLAŞMA KURUMLARI</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">1. RİBATLAR</text>\n  <text x="38" y="98" font-size="11" fill="#78350f">• Başlangıçta sınır boylarında</text>\n  <text x="46" y="114" font-size="11" fill="#78350f">savunma ve karakol yapıları</text>\n  <text x="38" y="138" font-size="11" fill="#78350f">• Güvenlik sağlandıkça</text>\n  <text x="46" y="154" font-size="11" font-weight="bold" fill="#b45309">kervansaray ve zaviyelere</text>\n  <text x="46" y="170" font-size="11" fill="#78350f">dönüştü.</text>\n  <text x="38" y="194" font-size="11" fill="#78350f">• Göçebe Türkmenlere İslam\'ın</text>\n  <text x="46" y="210" font-size="11" fill="#78350f">tebliğ edildiği irşat merkezleri.</text>\n\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">2. FÜTÜVVET ANLAYIŞI</text>\n  <text x="260" y="98" font-size="11" fill="#1e3a8a">• \'Fetâ\' (genç, yiğit, cömert)</text>\n  <text x="268" y="114" font-size="11" fill="#1e3a8a">kökünden gelen ahlaki ideal</text>\n  <text x="260" y="138" font-size="11" fill="#1e3a8a">• Nefsi terbiye etme, başkalarını</text>\n  <text x="268" y="154" font-size="11" font-weight="bold" fill="#1d4ed8">kendine tercih etme (îsâr)</text>\n  <text x="260" y="178" font-size="11" fill="#1e3a8a">• Kurallarını içeren eserlere</text>\n  <text x="268" y="194" font-size="11" font-weight="bold" fill="#1d4ed8">Fütüvvetname</text>\n  <text x="268" y="210" font-size="11" fill="#1e3a8a">adı verilmiştir.</text>\n\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">3. AHİLİK TEŞKİLATI</text>\n  <text x="483" y="98" font-size="11" fill="#14532d">• Anadolu\'da <tspan font-weight="bold">Ahi Evran</tspan></text>\n  <text x="491" y="114" font-size="11" fill="#14532d">öncülüğünde kuruldu.</text>\n  <text x="483" y="138" font-size="11" fill="#14532d">• Yamağı-çırak-kalfa-usta</text>\n  <text x="491" y="154" font-size="11" fill="#14532d">düzeniyle meslek ve ahlak</text>\n  <text x="491" y="170" font-size="11" fill="#14532d">eğitimini birleştirdi.</text>\n  <text x="483" y="194" font-size="11" font-weight="bold" fill="#15803d">• Dürüst ticaret ve kardeşlik</text>\n  <text x="491" y="210" font-size="11" fill="#14532d">ile İslamlaşmayı hızlandırdı.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
